import type { Metadata } from 'next';
import DocsLayout, {
  Code,
  Note,
  Section,
  T,
  Table,
} from '@/components/docs/DocsLayout';

// Public firmware API reference (spec §13). The endpoints themselves are static
// JSON generated by scripts/generate-api.mjs — see that script for the source
// of every field documented here.

export const metadata: Metadata = {
  title: 'Firmware API — OpenFC',
  description:
    'Public HTTP API for OpenFC firmware releases. Verify that a board is running an official, competition-certified build.',
};

export default function ApiDocs() {
  return (
    <DocsLayout
      title="Firmware API"
      active="/docs/api"
      intro={
        <>
          A public, unauthenticated HTTP API listing every published firmware
          release and its cryptographic hashes. Use it to confirm a board is
          running official, competition-legal firmware.
        </>
      }
    >
      <Section id="basics" title="Basics">
        <Table
          head={['', '']}
          rows={[
            ['Base URL', <T key="b">https://openfc.dev/api/v1</T>],
            ['Auth', 'None. Public and read-only.'],
            ['Format', 'JSON. Every response includes api_version and generated_at.'],
            ['CORS', 'Enabled for all origins.'],
            ['Rate limits', 'None. Static files behind a CDN.'],
          ]}
        />
        <p>
          The API is regenerated from the firmware manifest on every deploy, and
          the build fails if a published hash disagrees with the binary actually
          being served. A response can therefore never advertise a hash for a
          file that is not the file you would download.
        </p>
        <p>
          <T>api_version</T> only changes on a breaking change. New fields may be
          added within <T>v1</T>, so parse leniently and ignore unknown keys.
        </p>
      </Section>

      <Section id="endpoints" title="Endpoints">
        <Table
          head={['Endpoint', 'Returns']}
          rows={[
            [
              <T key="e">GET /api/v1/index.json</T>,
              'Service description and the endpoint list.',
            ],
            [
              <T key="e">GET /api/v1/firmware/latest.json</T>,
              'The newest competition-certified release.',
            ],
            [
              <T key="e">GET /api/v1/firmware/releases.json</T>,
              'Every published release, newest first.',
            ],
            [
              <T key="e">GET /api/v1/firmware/hashes.json</T>,
              'SHA-256 → release lookup, for verifying a connected board.',
            ],
          ]}
        />
      </Section>

      <Section id="latest" title="Latest certified firmware">
        <p>
          Answers &ldquo;what should this board be running?&rdquo;{' '}
          <T>latest</T> is <T>null</T> if nothing is currently certified.
        </p>
        <Code label="GET /api/v1/firmware/latest.json">{`{
  "api_version": "v1",
  "generated_at": "2026-07-31T01:39:53.093Z",
  "latest": {
    "version": "1.3.0",
    "released": "2026-07-31",
    "description": "Adds get_info and closes the raw-diagnostics watchdog gap",
    "changelog": "...",
    "binary_sha256": "0403cd4246c29d8e524b9f0cbe9300ea3fb399366996a1a8f8b61efd071b8887",
    "app_sha256": "0217fc0dbc1acb26c4e7ae9edbd3833a87ff8e530a83655e0d52db4a006fa3f7",
    "download_url": "https://openfc.dev/firmware/openfc-v1.3.0-merged.bin",
    "certified_for_competition": true,
    "min_hw_version": "1.1"
  }
}`}</Code>
      </Section>

      <Section id="hashes" title="Two hashes, and which one to use">
        <p>
          Each release publishes two SHA-256 values. Using the wrong one is the
          most common integration mistake, because both are valid hashes of
          &ldquo;the firmware&rdquo; — of different things.
        </p>
        <Table
          head={['Field', 'Hash of', 'Compare against']}
          rows={[
            [
              <T key="f">app_sha256</T>,
              'The application partition image',
              <>
                The <T>fw_hash</T> a connected board reports in <T>hello</T>.
              </>,
            ],
            [
              <T key="f">binary_sha256</T>,
              'The merged .bin file you download',
              'A file on disk, before flashing it.',
            ],
          ]}
        />
        <Note>
          To verify a <strong>connected board</strong>, use <T>app_sha256</T>.
          To verify a <strong>downloaded file</strong>, use{' '}
          <T>binary_sha256</T>. The lookup table below accepts either and tells
          you which one matched.
        </Note>
      </Section>

      <Section id="verify" title="Verifying a board for competition">
        <p>
          The board computes the SHA-256 of its own running application
          partition at boot and reports it as <T>fw_hash</T>. That is a hash of
          the code actually executing, not a version string a modified build
          could simply claim — so it is meaningful evidence rather than a
          self-declaration.
        </p>
        <p>Three steps:</p>
        <ol className="ml-5 list-decimal space-y-1">
          <li>
            Send <T>&#123;&quot;cmd&quot;:&quot;get_info&quot;&#125;</T> and read{' '}
            <T>fw_hash</T> from the <T>hello</T> reply.
          </li>
          <li>
            Fetch <T>/api/v1/firmware/hashes.json</T>.
          </li>
          <li>
            Look up the hash. It is competition-legal only when the entry exists
            and <T>certified_for_competition</T> is <T>true</T>.
          </li>
        </ol>
        <Code label="GET /api/v1/firmware/hashes.json">{`{
  "api_version": "v1",
  "generated_at": "2026-07-31T01:39:53.093Z",
  "hashes": {
    "0217fc0dbc1acb26c4e7ae9edbd3833a87ff8e530a83655e0d52db4a006fa3f7": {
      "version": "1.3.0", "certified_for_competition": true, "kind": "app"
    },
    "0403cd4246c29d8e524b9f0cbe9300ea3fb399366996a1a8f8b61efd071b8887": {
      "version": "1.3.0", "certified_for_competition": true, "kind": "binary"
    }
  }
}`}</Code>
        <Code label="node — inspection check">{`const hashes = await fetch(
  'https://openfc.dev/api/v1/firmware/hashes.json'
).then((r) => r.json());

const entry = hashes.hashes[fwHash.toLowerCase()];

if (!entry)                                console.log('FAIL — unknown firmware');
else if (!entry.certified_for_competition) console.log('FAIL — uncertified build');
else                                       console.log('PASS —', entry.version);`}</Code>
        <Note kind="warn">
          A hash that is absent from the table is not necessarily malicious — it
          is most often a self-built or development firmware. It does mean the
          board is not running a build we published, so it cannot be treated as
          certified.
        </Note>
      </Section>

      <Section id="client" title="TypeScript client">
        <p>
          This site&apos;s own client is importable if you are working in
          TypeScript. It wraps the same endpoints and returns a single verdict.
        </p>
        <Code label="lib/openfc-api.ts">{`import { verifyFirmware } from '@/lib/openfc-api';

const verdict = await verifyFirmware(fwHash, 'https://openfc.dev');

verdict.certified     // legal for competition
verdict.recognised    // a published build, certified or not
verdict.version       // "1.3.0"
verdict.outdated      // a newer certified release exists
verdict.latestVersion // "1.3.0"`}</Code>
        <p>
          <T>verdictFor()</T> is the same logic as a pure function, if you want
          to cache the index and check many boards offline.
        </p>
      </Section>

      <Section id="update" title="Checking for updates">
        <Code label="is this board up to date?">{`const { latest } = await fetch(
  'https://openfc.dev/api/v1/firmware/latest.json'
).then((r) => r.json());

if (latest && fwHash.toLowerCase() !== latest.app_sha256) {
  console.log('Update available:', latest.version, '→', latest.download_url);
}`}</Code>
        <p>
          Compare hashes rather than version strings: the hash distinguishes a
          genuine release from a local build that reports the same version
          number.
        </p>
      </Section>

      <Section id="stability" title="Stability">
        <p>
          Endpoint paths and existing field names within <T>v1</T> will not
          change or be removed. A published release is never edited or deleted —
          if a build is withdrawn, <T>certified_for_competition</T> flips to{' '}
          <T>false</T> and the entry stays, so an old hash always resolves to a
          truthful answer rather than disappearing.
        </p>
      </Section>
    </DocsLayout>
  );
}
